def parse_gff(path):
 genes={};txs={};bytx=defaultdict(list)
 for line in open(path):
  if line.startswith('#'):continue
  f=line.rstrip().split('\t');attrs=dict(x.split('=',1) for x in f[8].split(';') if '=' in x)
  if f[2]=='gene':
   genes[attrs['Name']]={'id':attrs.get('ID'),'start':int(f[3]),'end':int(f[4]),'strand':f[6]}
  elif f[2]=='mRNA':
   txid=attrs['transcript_id']; parent=attrs.get('Parent','').replace('gene:','')
   # find gene symbol from ID or Parent map later
   txs[txid]={'id':txid,'parent':parent,'name':attrs.get('Name'),'start':int(f[3]),'end':int(f[4]),'strand':f[6],'gene':None}
   bytx[txid].append(('tx',txid,None))
  elif f[2] in ('exon','CDS','five_prime_UTR','three_prime_UTR'):
   tid=attrs.get('Parent','').replace('transcript:','')
   bytx[tid].append((f[2],int(f[3]),int(f[4]),f[7]))
 # map transcript to gene symbol
 id2sym={v['id']:k for k,v in genes.items()}
 for tid,t in txs.items():t['gene']=id2sym.get(t['parent'])
 out={}
 for tid,t in txs.items():
  tr=Transcript(t['gene'],tid,t['strand'],t['start'],t['end'])
  for x in bytx[tid]:
   typ=x[0]
   if typ=='exon':tr.exons.append((x[1],x[2]))
   elif typ=='CDS':tr.cds.append((x[1],x[2],int(x[3]) if x[3]!='.' else None))
   elif typ=='five_prime_UTR':tr.utr5.append((x[1],x[2]))
   elif typ=='three_prime_UTR':tr.utr3.append((x[1],x[2]))
  out[tid]=tr
 return genes,out

def segments(tr,kind):
 seg=getattr(tr,kind)
 if tr.strand=='+':return sorted(seg)
 return sorted(((b,a) for a,b,*_ in seg))

def cds_positions(tr):
 # returns genomic positions in transcript order and codon index (0-based)
 pos=[]
 for a,b in sorted(tr.cds,key=lambda x:x[0]):
  # For minus strand, sort descending within exon and all exons in transcript order
  pass
 # Need exon-aware ordering; order CDS blocks by transcript direction. Build exon groups and sort CDS by exon rank.
 exons=segments(tr,'exons'); ranks={}
 for i,(a,b) in enumerate(exons):
  for p in range(a,b+1):ranks[p]=i
 blocks=[]
 for a,b,ph in tr.cds:
  # group phase by sorted exon but phase attached to each CDS block
  blocks.append((ranks[a],a,b,ph))
 blocks.sort(key=lambda x:x[0],reverse=(tr.strand=='-'))
 for _,a,b,ph in blocks:
  rng=range(a,b+1) if tr.strand=='+' else range(b,a-1,-1)
  pos.extend(rng)
 return pos
